<template><div v-if="open" class="fixed inset-0 z-50 bg-slate-950/50 flex items-center justify-center p-4"><form class="w-full max-w-md rounded-2xl bg-white p-6 space-y-4" aria-label="Form ajukan bid" @submit.prevent="submit"><h2 class="text-xl font-bold">Ajukan Bid</h2><p class="text-sm text-slate-600">Bid harus lebih tinggi dari bid tertinggi saat ini.</p><label class="label" for="bid-amount-input">Nominal bid</label><input id="bid-amount-input" v-model.number="bid" class="input" type="number" :min="minimum" required/><div class="flex gap-2"><button type="button" class="btn-secondary" @click="$emit('close')">Batal</button><button type="submit" class="btn-primary">Kirim Bid</button></div></form></div></template><script setup>import {ref,computed,watch} from 'vue';const props=defineProps({open:Boolean,current:Number});const emit=defineEmits(['close','submit']);const bid=ref(0);const minimum=computed(()=>Number(props.current||0)+1);watch(()=>props.open,v=>{if(v)bid.value=minimum.value});function submit(){if(bid.value>=minimum.value)emit('submit',bid.value)}</script>